SELECT v.id AS visit_id, v.visit_time, i.url, v.title, CASE v.origin WHEN 0 THEN 'local' WHEN 1 THEN 'synced' ELSE CAST(v.origin AS TEXT) END AS origin,
  v.load_successful, (SELECT i2.url FROM history_visits v2 JOIN history_items i2 ON i2.id = v2.history_item WHERE v2.id = v.redirect_source) AS redirect_from, i.visit_count, v.http_non_get
FROM history_visits v JOIN history_items i ON i.id = v.history_item ORDER BY v.visit_time DESC, v.id DESC;

SELECT u.url AS adress, u.title AS titel, u.visit_count AS besok, u.typed_count AS skriven, CASE WHEN u.last_visit_time > 0 THEN datetime(u.last_visit_time / 1000000 - 11644473600, 'unixepoch', 'localtime') END AS senaste_lokal,
  CASE WHEN u.hidden = 1 THEN 'ja' ELSE 'nej' END AS dold, u.id AS url_id
FROM urls u ORDER BY u.visit_count DESC, u.last_visit_time DESC;

